int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (bb.remaining() < 1) break;
            byte b2 = bb.get();
            if ((b2 & 0xC0) != 0x80) break;
            char ch = (char) (((b & 0x1F) << 6) | (b2 & 0x3F));
            sb.append(ch);
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() < 2) break;
            byte b2 = bb.get();
            byte b3 = bb.get();
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) break;
            char ch = (char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
            sb.append(ch);
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            if (bb.remaining() < 3) break;
            byte b2 = bb.get();
            byte b3 = bb.get();
            byte b4 = bb.get();
            if ((b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80 || (b4 & 0xC0) != 0x80) break;
            int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            sb.append(Character.toChars(codePoint));
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            break;
        }
    }
    return i;
}

