    final long FETCH_DATA_DURATION = 3600000; // Example value, replace with actual constant if available

    if (start >= end) {
        return timeRanges; // Return empty list if start is not before end
    }

    while (start < end) {
        long newEnd = Math.min(start + FETCH_DATA_DURATION, end);
