static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    int firstDayOfMonth = 1;
    // Calculate the last day of the month
    int lastDayOfMonth = 31; // Simplified, does not account for actual month length
    if (month == 4 || month == 6 || month == 9 || month == 11) {
        lastDayOfMonth = 30;
    } else if (month == 2) {
        // Simplified, does not account for leap years
        lastDayOfMonth = 28;
    }

    // Find the closest dayStep aligned day
    int alignedDay = ((day - 1) / dayStep) * dayStep + 1;
    if (alignedDay < firstDayOfMonth) {
        alignedDay = firstDayOfMonth;
    } else if (alignedDay > lastDayOfMonth) {
        alignedDay = lastDayOfMonth;
    }

    return year * 10000L + month * 100L + alignedDay;
}

int function ( CharSequence str , int index , int len ) {
    if ( str == null ) {
        throw new IllegalArgumentException( "Input string cannot be null" );
    }
    if ( index < 0 || len < 0 || index + len > str.length() ) {
        throw new IllegalArgumentException( "Invalid index or length" );
    }
    int size = 0;
    for ( int i = index; i < index + len; i++ ) {
        char ch = str.charAt( i );
        if ( ch <= 0x7F ) {
            size += 1;
        } else if ( ch <= 0x7FF ) {
            size += 2;
        } else if ( Character.isHighSurrogate( ch ) ) {
            if ( i + 1 < index + len && Character.isLowSurrogate( str.charAt( i + 1 ) ) ) {
                size += 4; // surrogate pair
                i++; // skip the low surrogate
            } else {
                size += 3; // unpaired high surrogate
            }
        } else {
            size += 3;
        }
    }
    return size;
}

