LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }
    int len = str.length();
    int utfLen = 0;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            utfLen++;
        } else if (c <= 0x7FF) {
            utfLen += 2;
        } else if (Character.isHighSurrogate(c)) {
            if (i + 1 < len && Character.isLowSurrogate(str.charAt(i + 1))) {
                utfLen += 4;
                i++;
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            utfLen += 3;
        }
    }
    lb = ensureCapacity(utfLen, session, lb);
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.buffer[lb.offset++] = (byte) c;
        } else if (c <= 0x7FF) {
            lb.buffer[lb.offset++] = (byte) (0xC0 | (c >> 6));
            lb.buffer[lb.offset++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isHighSurrogate(c)) {
