public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    while (!isPrime(candidate)) {
        candidate += 2;
    }
    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = findClosestPrime(desiredCapacity);
    }
    return candidate;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

private static int findClosestPrime(int desiredCapacity) {
    int lower = desiredCapacity;
    int upper = desiredCapacity;
    while (true) {
        if (lower > 1 && isPrime(lower)) {
            return lower;
        }
        if (isPrime(upper)) {
            return upper;
        }
        lower--;
        upper++;
    }
}

