protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    List<E> edgeList = new ArrayList<>(tour);
    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();
    V startVertex = null;

    // Find a starting vertex
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        if (!tour.contains(graph.getEdge(source, graph.getEdgeTarget(edge)))) {
            startVertex = source;
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
    }

    V currentVertex = startVertex;
    path.setStartVertex(currentVertex);

    while (!edgeList.isEmpty()) {
        E nextEdge = null;
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
        }
        path.addEdge(nextEdge);
        currentVertex = graph.getEdgeTarget(nextEdge);
        edgeList.remove(nextEdge);
    }

    path.setEndVertex(currentVertex);

    if (!currentVertex.equals(startVertex)) {
        throw new IllegalArgumentException("The provided set of edges does not form a valid tour");
    }

    return path;
}

