    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket == null) {
        return; // No vertices to move
    }

    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    if (zeroLabelBucket == null) {
        zeroLabelBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroLabelBucket);
    }

    for (Integer vertex : minLabelBucket) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds");
        }
        labels.set(vertex, 0);
        zeroLabelBucket.add(vertex);
    }

    minLabelBucket.clear();
}

