        while (true) {
            char nextChar = (char) System.in.read();
            if (nextChar == -1) {
                break; // End of input
            }
            boolean isTerminator = false;
            for (char terminator : terminators) {
                if (nextChar == terminator) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break;
            }
            token.append(nextChar);
        }
    } catch (IOException e) {
        // Handle possible I/O errors
        e.printStackTrace();
    }
    return token.toString();
}

