String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the paths by removing any trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the relative path into parts
    String[] parts = relativePath.split("/");
    StringBuilder result = new StringBuilder(path);

    for (String part : parts) {
        if (part.equals("..")) {
            // Move up one directory if possible
            int lastSlashIndex = result.lastIndexOf("/");
            if (lastSlashIndex != -1) {
                result.setLength(lastSlashIndex);
            }
        } else if (!part.equals(".")) {
            // Append the part to the result
            result.append("/").append(part);
        }
    }

    return result.toString();
}

